export const TIME_UNITS = {
    millisecond: 1,
    second: 1000,
    minute: 60000,
    hour: 3600000,
    day: 24 * 3600000,
    week: 7 * 24 * 3600000,
    month: 28 * 24 * 3600000,
    quarter: 62 * 24 * 3600000,
    halfYear: 160 * 24 * 3600000,
    year: 364 * 24 * 3600000,
};
export const DATETIME_LABEL_FORMATS = {
    millisecond: 'DD.MM.YY HH:mm:ss.SSS',
    second: 'DD.MM.YY HH:mm:ss',
    minute: 'DD.MM.YY HH:mm',
    hour: 'DD.MM.YY HH:mm',
    day: 'DD.MM.YY',
    week: 'DD.MM.YY',
    month: "MMM 'YY",
    quarter: "MMM 'YY",
    halfYear: "MMM 'YY",
    year: 'YYYY',
};
function getTimeUnit(range) {
    const units = Object.keys(TIME_UNITS);
    const index = units.findIndex((unit) => range < TIME_UNITS[unit]);
    return index === -1 ? 'year' : units[index - 1];
}
export function getDefaultDateFormat(range, overrides) {
    const formats = Object.assign(Object.assign({}, DATETIME_LABEL_FORMATS), overrides);
    if (range) {
        const unit = getTimeUnit(range);
        if (unit in formats) {
            return formats[unit];
        }
    }
    return formats.day;
}
export function getDefaultTimeOnlyFormat(step) {
    if (step < TIME_UNITS.second) {
        return 'HH:mm:ss.SSS';
    }
    if (step < TIME_UNITS.minute) {
        return 'HH:mm:ss';
    }
    return 'HH:mm';
}
